    // Sort the map by keys
    std::sort(myMap.begin(), myMap.end());

    // Print the sorted keys and their corresponding values
    for (const auto& pair : myMap) {
        std::cout << "Key: " << pair.first << ", Value: " << pair.second << std::endl;
    }

    return 0;
}
```

