```cpp
#include <iostream>
#include <map>
#include <algorithm>

using namespace std;

int main() {
    // Create a map to store student names and ages
    map<string, int> studentInfo;
    studentInfo.insert(make_pair("Alice", 22));
    studentInfo.insert(make_pair("Bob", 25));
    studentInfo.insert(make_pair("Charlie", 18));
    studentInfo.insert(make_pair("Diana", 29));

    // Sort the map by ages in descending order
    sort(studentInfo.begin(), studentInfo.end(), 
        [](const pair<string, int> &a, const pair<string, int> &b) {
            return a.second > b.second;  // Compare based on ages
        });

    // Print out the sorted map
    for (auto &info : studentInfo) {
        cout << info.first << ": " << info.second << "\n";
    }

    return 0;
}
```

